import type { TableName } from '../db'

declare global {
    namespace Now {
        /**
         * Creates a reference to a record identified by coalesce keys.
         *
         * @param table - The target table name (e.g. `'sys_user_role'`)
         * @param keys - An object of coalesce key-value pairs used to uniquely identify the record
         *
         * @example
         * ```ts
         * Now.ref('sys_user_role', { name: 'admin' })
         * ```
         */
        function ref(table: TableName, keys: { [key: string]: string }): any
        /**
         * Creates a reference to a record identified by a GUID or a `Now.ID` key.
         *
         * When a `Now.ID` key is provided instead of a GUID, it is lazily resolved
         * to a sys_id during the build process.
         *
         * @param table - The target table name (e.g. `'sys_hub_flow'`)
         * @param guid - A sys_id GUID or a `Now.ID` key string (e.g. `'my-flow'`)
         * @param keys - Optional coalesce keys to use as a fallback identifier
         *
         * @example
         * ```ts
         * // Reference by GUID
         * Now.ref('sys_hub_flow', 'a1b2c3d4e5f6...')
         *
         * // Reference by Now.ID key
         * Now.ref('sys_hub_flow', 'my-flow')
         *
         * // Reference by GUID with coalesce keys fallback
         * Now.ref('sys_hub_flow', 'a1b2c3d4e5f6...', { name: 'My Flow' })
         * ```
         */
        function ref(table: TableName, guid: string, keys?: { [key: string]: string }): any
    }
}
